function crIdentity(){if(!state.user)return;const generation=typeof companyAuthSnapshot==='function'?companyAuthSnapshot().generation:null;if(cr.userId!==state.user.id||generation!==null&&cr.authGeneration!==generation){crReset();cr.userId=state.user.id;cr.authGeneration=generation;}}
