  render();const next=document.querySelector?.('.cr-panel');if(!next)return;const nextSyncDetails=next.querySelector('[data-cr-sync-sources]');if(nextSyncDetails&&typeof syncDetailsOpen==='boolean')nextSyncDetails.open=syncDetailsOpen;const nextQuery=next.querySelector('[data-cr-search] [name="query"]');if(nextQuery&&value!==undefined)nextQuery.value=value;
