const crButton=(label,action,attrs='',classes='small quiet')=>button(label,'creative-'+action,'',classes,attrs);
function crTime(value){if(!value)return '시각 모름';const date=new Date(value);if(!Number.isFinite(date.getTime()))return '시각 모름';return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'numeric',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).format(date);}
