function crCountry(code){if(code==='GLOBAL')return '국가 구분 없음';if(wrRegions[code])return wrRegions[code];try{return new Intl.DisplayNames(['ko'],{type:'region'}).of(code)||code;}catch{return code;}}
function crObservationTime(row){return ['official-page','research-report'].includes(row.provenance)?crTime(row.checkedAt):new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'numeric',day:'numeric'}).format(new Date(row.checkedAt));}
function crReportProvider(provider){return provider==='gemini-spark'?'Gemini 예약 조사':'일일 조사';}
